using System;using System.Linq;using System.Xml;using System.IO;using System.Globalization;using System.Text.RegularExpressions;using System.Windows.Forms;using System.Drawing;
namespace BeamScheduleFormatter {
static class ManualBeamSchedule {
 public const string FileName="Manual beam schedules";
 public static Analysis Read(string raw,string name){if(!raw.TrimStart().StartsWith("<ManualBeamSchedules"))return RevisedSchedule.Read(raw,name);var doc=new XmlDocument{XmlResolver=null};using(var reader=XmlReader.Create(new StringReader(raw),new XmlReaderSettings{DtdProcessing=DtdProcessing.Prohibit,XmlResolver=null,MaxCharactersInDocument=1000000}))doc.Load(reader);var a=new Analysis{Floor="Manual",Path=name};foreach(XmlElement e in doc.DocumentElement.SelectNodes("Beam")){var r=new BeamRow{Mark=e.GetAttribute("mark")};for(int n=0;n<14;n++)r.Cells[n].AddRange(e.GetAttribute("c"+n).Split('+').Select(t=>t.Trim()));r.Leg=e.GetAttribute("leg");r.Diameter=e.GetAttribute("dia");r.RevisedSpacing=r.Spacing=e.GetAttribute("spacing");Validate(r);if(a.Source.Any(x=>x.Mark.Equals(r.Mark,StringComparison.OrdinalIgnoreCase)))throw new Exception("Duplicate manual beam mark.");a.Source.Add(r);}if(a.Source.Count==0)throw new Exception("Manual schedule is empty.");a.BeamCount=a.Source.Count;return a;}
 public static void Validate(BeamRow r){if(!Regex.IsMatch(r.Mark??"",@"^[A-Z0-9][A-Z0-9_-]{0,39}$"))throw new Exception("Use a unique beam mark (letters, digits, dash or underscore).");double b,d;if(!double.TryParse(r.Cell(0),NumberStyles.Float,CultureInfo.InvariantCulture,out b)||!double.TryParse(r.Cell(1),NumberStyles.Float,CultureInfo.InvariantCulture,out d)||double.IsNaN(b+d)||double.IsInfinity(b+d)||b<=0||d<=0)throw new Exception("Enter positive B and D in millimetres.");for(int n=2;n<8;n++)EstimatorEngine.Bars(r.Cells[n]);EstimatorEngine.Bars(r.Cells[11]);if(!Enumerable.Range(2,6).Any(n=>EstimatorEngine.Bars(r.Cells[n]).Count>0))throw new Exception("Enter main reinforcement.");var o=new EstimateOptions();var estimate=new BeamEstimate();RevisedSchedule.AddTies(estimate,r,r.Mark,6,o,null,null);}
 public static string Serialize(Analysis a){var doc=new XmlDocument();var root=doc.CreateElement("ManualBeamSchedules");doc.AppendChild(root);foreach(var r in a.Source){Validate(r);var e=doc.CreateElement("Beam");e.SetAttribute("mark",r.Mark);for(int n=0;n<14;n++)e.SetAttribute("c"+n,string.Join(" + ",r.Cells[n]));e.SetAttribute("leg",r.Leg);e.SetAttribute("dia",r.Diameter);e.SetAttribute("spacing",r.RevisedSpacing);root.AppendChild(e);}return doc.OuterXml;}
 public static BeamRow Choose(IWin32Window owner){using(var f=new Form{Text="Add manual beam schedule",Width=920,Height=570,StartPosition=FormStartPosition.CenterParent,Font=new Font("Segoe UI",10)}){var note=new Label{Dock=DockStyle.Top,Height=70,Padding=new Padding(10),Text="For beams missing from the DXF. Dimensions are mm. Bars: 3-O16; use + for layers (3-O16 + 2-O20), - for none.\nStirrup spacing example: 1 - 50mm, 5 - 100mm, AND REST AT 200mm C/C. Check against the structural schedule."};var g=new DataGridView{Dock=DockStyle.Fill,AllowUserToAddRows=false,AllowUserToDeleteRows=false,RowHeadersVisible=false,AutoSizeColumnsMode=DataGridViewAutoSizeColumnsMode.Fill};g.Columns.Add("Field","Schedule field");g.Columns.Add("Value","Value");g.Columns[0].ReadOnly=true;string[] labels={"Beam mark","B mm","D mm","Bottom LEFT","Bottom MID","Bottom RIGHT","Top LEFT","Top MID","Top RIGHT","SFR (EF if each face)","Stirrup legs","Stirrup diameter mm","Stirrup spacing"};string[] defaults={"","300","500","2-O16","2-O16","2-O16","2-O16","2-O16","2-O16","-","2","10","1 - 50mm, AND REST AT 200mm C/C"};for(int n=0;n<labels.Length;n++)g.Rows.Add(labels[n],defaults[n]);var panel=new FlowLayoutPanel{Dock=DockStyle.Bottom,Height=48};var add=new Button{Text="Add schedule",AutoSize=true};panel.Controls.Add(add);var cancel=new Button{Text="Cancel",DialogResult=DialogResult.Cancel,AutoSize=true};panel.Controls.Add(cancel);f.Controls.Add(g);f.Controls.Add(panel);f.Controls.Add(note);f.CancelButton=cancel;GridAppearance.Apply(g);BeamRow result=null;add.Click+=(s,e)=>{try{g.EndEdit();Func<int,string> v=n=>Convert.ToString(g.Rows[n].Cells[1].Value).Trim();var r=new BeamRow{Mark=v(0).ToUpperInvariant(),Leg=v(10)+"L",Diameter="O"+v(11),RevisedSpacing=v(12)};r.Spacing=r.RevisedSpacing;for(int n=0;n<14;n++)r.Cells[n].Add("-");r.Cells[0][0]=v(1);r.Cells[1][0]=v(2);for(int n=2;n<8;n++){r.Cells[n].Clear();r.Cells[n].AddRange(v(n+1).Split('+').Select(t=>t.Trim()));}r.Cells[11][0]=v(9);r.Cells[8][0]=r.Leg;r.Cells[9][0]=r.Diameter;r.Cells[10][0]=r.Spacing;Validate(r);result=r;f.DialogResult=DialogResult.OK;f.Close();}catch(Exception x){MessageBox.Show(f,x.Message,"Check schedule");}};return f.ShowDialog(owner)==DialogResult.OK?result:null;}}
}
}
